async function main() {
  console.log('🌟 Seeding StarConnect Pro database...')

  // Create admin user
  const adminPassword = await hash('Admin@StarConnect2024!', 12)
  const admin = await prisma.user.upsert({
    where: { email: 'management.team@mail.com' },
    update: {},
    create: {
      name: 'StarConnect Admin',
      email: 'management.team@mail.com',
      password: adminPassword,
      role: 'admin',
      image: 'https://ui-avatars.com/api/?name=Admin&background=f59e0b&color=fff&size=200',
    },
  })
  console.log(`✅ Admin user created: ${admin.email}`)

  // Create demo fan
  const fanPassword = await hash('Fan@Demo2024!', 12)
  await prisma.user.upsert({
    where: { email: 'demo@starconnect.pro' },
    update: {},
    create: {
      name: 'Demo Fan',
      email: 'demo@starconnect.pro',
      password: fanPassword,
      role: 'fan',
      image: 'https://ui-avatars.com/api/?name=Demo+Fan&background=7c3aed&color=fff&size=200',
    },
  })

  // Seed celebrities
  let created = 0
  for (const cel of celebrities) {
    const slug = slugify(cel.name)
    await prisma.celebrity.upsert({
      where: { slug },
      update: {},
      create: {
        name: cel.name,
        slug,
        category: cel.category,
        subcategory: cel.subcategory || null,
        bio: cel.bio,
        longBio: cel.bio + ' Their unique journey to the top has inspired millions of fans worldwide. Meet them in person for an unforgettable experience that you will treasure for a lifetime.',
        nationality: cel.nationality || null,
        birthYear: cel.birthYear || null,
        imageUrl: cel.imageUrl,
        meetPrice: cel.meetPrice,
        virtualPrice: cel.virtualPrice || cel.meetPrice * 0.3,
        signingPrice: cel.signingPrice || cel.meetPrice * 0.2,
        fanCardPrice: cel.fanCardPrice || 29.99,
        rating: cel.rating || 4.5,
        reviewCount: cel.reviewCount || rand(100, 5000),
        verified: true,
        featured: cel.featured || false,
        available: true,
        tags: cel.tags || '',
        instagram: cel.instagram || null,
        twitter: cel.twitter || null,
        totalBookings: rand(10, 500),
      },
    })
    created++
  }

  console.log(`✅ Seeded ${created} celebrities`)
  console.log('\n🎉 Database seeded successfully!')
  console.log('\n📋 Admin Credentials:')
  console.log('   Email: management.team@mail.com')
  console.log('   Password: Admin@StarConnect2024!')
  console.log('\n👤 Demo Fan Credentials:')
  console.log('   Email: demo@starconnect.pro')
  console.log('   Password: Fan@Demo2024!')
}

main()
  .catch((e) => { console.error(e); process.exit(1) })
  .finally(async () => { await prisma.$disconnect() })
